// Verifies the HMAC from Convex over `${timestamp}.${rawBody}` and drops replays.
// Secret comes from the container environment, never from this workflow.
const crypto = require('crypto');
const secret = $env.LENDLOOP_WEBHOOK_SECRET;
const item = $input.first();
const h = item.json.headers || {};
const ts = h['x-lendloop-timestamp'];
const sig = h['x-lendloop-signature'] || '';
const raw = item.binary && item.binary.data
  ? (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8')
  : JSON.stringify(item.json.body);

const fresh = ts && Math.abs(Date.now() / 1000 - Number(ts)) <= 300;
const expected = 'sha256=' + crypto.createHmac('sha256', secret || '').update(`${ts}.${raw}`).digest('hex');
const valid = !!secret && fresh && sig.length === expected.length &&
  crypto.timingSafeEqual(Buffer.from(sig), Buffer.from(expected));
if (!valid) return [{ json: { valid: false } }];

const body = JSON.parse(raw);
// Idempotency on our side too: Convex may retry a delivery whose response was lost.
const store = $getWorkflowStaticData('global');
store.seen = store.seen || [];
const duplicate = store.seen.includes(body.eventId);
if (!duplicate) store.seen = [...store.seen, body.eventId].slice(-1000);

return [{ json: { valid: true, duplicate, event: body } }];

// Uses only the fields the message needs: recipient name/email, tool name, dates, status.
const { duplicate, event } = $input.first().json;
if (duplicate) return [{ json: { skip: true, eventId: event.eventId } }];
const r = event.recipient;
const lines = {
  'loan.requested': `${r.name}, a neighbor asked to borrow your ${event.tool.name} from ${event.startDate} to ${event.endDate}. Open LendLoop to approve or decline.`,
  'loan.cancelled': `${r.name}, the request for your ${event.tool.name} (${event.startDate} to ${event.endDate}) was cancelled.`,
  'loan.approved': `${r.name}, good news: your request for the ${event.tool.name} (${event.startDate} to ${event.endDate}) was approved.`,
  'loan.declined': `${r.name}, your request for the ${event.tool.name} (${event.startDate} to ${event.endDate}) was declined.`,
  'loan.returned': `${r.name}, thanks for returning the ${event.tool.name}. The loan is closed.`,
};
return [{ json: {
  skip: false,
  eventId: event.eventId,
  to: r.email,
  subject: `LendLoop: ${event.tool.name} (${event.event.replace('loan.', '')})`,
  text: lines[event.event] || `Update on ${event.tool.name}: ${event.status}`,
} }];

// Mock channel: logs the message. Swap this node for 'Send Email' (SMTP credential)
// or Slack/Discord; the input already has { to, subject, text }.
const m = $input.first().json;
if (m.skip) return [{ json: { delivered: false, duplicate: true, eventId: m.eventId } }];
console.log(`[LendLoop notify] to=${m.to} subject="${m.subject}" text="${m.text}"`);
return [{ json: { delivered: true, channel: 'mock-log', eventId: m.eventId } }];
